import type {
  BtkiEntry,
  LartasLevel,
  PermitRequirement,
  RiskTier,
  SniRequirement,
  Uom,
} from "../types";
import mfn from "./tariff-mfn.json" with { type: "json" };

/**
 * Indonesian tariff register (BTKI 2022 / AHTN 2022).
 *
 * Rates are NOT hand-typed. `bm` is read from `tariff-mfn.json`, which is
 * generated by `scripts/fetch-tariff.mjs` from the World Bank WITS / TRAINS
 * dataset — reporter 360 (Indonesia), partner 000 (MFN), applied rates, 2022.
 * That is the schedule BTKI 2022 implements, so the number on screen is the
 * number in the tariff book rather than a plausible-looking guess.
 *
 * Where a six-digit subheading splits into national lines taxed at different
 * rates, TRAINS reports the range. We carry the range and calculate at its
 * ceiling, and the row is flagged for confirmation instead of quietly picking
 * a number. `bmExact` records whether the subheading was uniform.
 */

type RateRow = { min: number; max: number; avg: number; lines: number; year: string };
const RATES = (mfn as { rates: Record<string, RateRow> }).rates;
export const TARIFF_SOURCE = (mfn as { source: string; fetched: string }).source;
export const TARIFF_FETCHED = (mfn as { fetched: string }).fetched;

/** Scheme keys, in the order the advisory panel lists them. */
export type FtaScheme = "ACFTA" | "ATIGA" | "IJEPA" | "AIFTA";

export interface TariffEntry extends BtkiEntry {
  /** Six-digit subheading the MFN rate was reported at. */
  hs6: string;
  /** True when every national line in the subheading carries the same rate. */
  bmExact: boolean;
  /** Lowest rate inside the subheading, when it is not uniform. */
  bmMin?: number;
  /** Ceiling of the subheading range — the rate used for calculation. */
  bmMax: number;
  /** Free-trade scheme rates. Missing key = no preference, MFN applies. */
  fta: Partial<Record<FtaScheme, number>>;
  /** Words that identify this line when reading a supplier document. */
  keys: string[];
  /** Goods excluded from the PPFTZ-01 suspension (excise goods). */
  ftzBlocked?: boolean;
  /** Set when the register cannot separate this line from its siblings. */
  caution?: string;
}

interface Seed {
  hs: string;
  id: string;
  en: string;
  uom: Uom;
  keys?: string[];
  lartas?: LartasLevel;
  permits?: PermitRequirement[];
  sni?: SniRequirement;
  ppnbm?: number;
  /** Scheme overrides. Default for industrial chapters is 0 % on ACFTA/ATIGA. */
  fta?: Partial<Record<FtaScheme, number>>;
  /** Explicit MFN rate when the subheading range is too wide to use as-is. */
  bm?: number;
  risk?: RiskTier;
  ftzBlocked?: boolean;
  note?: string;
}

