/**
 * Chapters where Indonesia's ACFTA schedule is not at zero across the board.
 * Textiles, footwear, steel and furniture sit on the sensitive track, which
 * retains a 5 % residual rate; alcohol and tobacco are excluded outright.
 */
const ACFTA_FIVE = new Set(["61", "62", "63", "64", "72", "73", "94"]);

function schemeDefaults(chapter: string): Partial<Record<FtaScheme, number>> {
  if (chapter === "22" || chapter === "24") {
    // Alcohol and tobacco are excluded from ACFTA/ATIGA tariff elimination.
    return {};
  }
  if (ACFTA_FIVE.has(chapter)) {
    return { ACFTA: 0.05, ATIGA: 0, IJEPA: 0.05, AIFTA: 0.05 };
  }
  return { ACFTA: 0, ATIGA: 0, IJEPA: 0, AIFTA: 0.05 };
}

