/* ---------------- resolution ---------------- */

interface ResolvedRate {
  /** Rate used for calculation: exact when the subheading is uniform, else its ceiling. */
  bm: number;
  bmMax: number;
  bmMin?: number;
  bmExact: boolean;
}

function resolveBm(seed: Seed): ResolvedRate {
  const hs6 = seed.hs.replace(/\./g, "").slice(0, 6);
  const row = RATES[hs6];
  if (seed.bm !== undefined) {
    return { bm: seed.bm, bmMax: seed.bm, bmExact: true };
  }
  if (!row) {
    // No reported rate for the subheading — refuse to invent one.
    return { bm: 0, bmMax: 0, bmExact: false };
  }
  const uniform = row.min === row.max;
  return {
    bm: row.max / 100,
    bmMax: row.max / 100,
    bmMin: uniform ? undefined : row.min / 100,
    bmExact: uniform,
  };
}

function toEntry(seed: Seed): TariffEntry {
  const hs6 = seed.hs.replace(/\./g, "").slice(0, 6);
  const chapter = hs6.slice(0, 2);
  const rate = resolveBm(seed);
  const fta = { ...schemeDefaults(chapter), ...(seed.fta ?? {}) };

  const lartas: LartasLevel = seed.lartas ?? "NONE";
  return {
    hs: seed.hs,
    hsCompact: seed.hs.replace(/\./g, ""),
    hs6,
    titleId: seed.id,
    titleEn: seed.en,
    uom: seed.uom,
    bmMfn: rate.bm,
    bmMax: rate.bmMax,
    bmMin: rate.bmMin,
    bmExact: rate.bmExact,
    // Kept for the older BtkiEntry shape; the engine reads `fta` instead.
    bmAcf: fta.ACFTA ?? rate.bm,
    bmAsean: fta.ATIGA ?? rate.bm,
    ppnbm: seed.ppnbm ?? 0,
    lartas,
    permits: seed.permits,
    sni: seed.sni,
    risk: seed.risk ?? "LOW",
    rationale: seed.note ?? seed.en,
    fta,
    keys: seed.keys ?? [],
    ftzBlocked: seed.ftzBlocked,
    caution: seed.note,
  };
}

export const TARIFF: TariffEntry[] = SEEDS.map(toEntry);

export const TARIFF_BY_HS: Record<string, TariffEntry> = Object.fromEntries(
  TARIFF.map((e) => [e.hs, e]),
);

/** Lookup that never fabricates: returns undefined for an unknown heading. */
export function findTariff(hs: string): TariffEntry | undefined {
  const direct = TARIFF_BY_HS[hs];
  if (direct) return direct;
  const compact = hs.replace(/\D/g, "");
  return TARIFF.find((e) => e.hsCompact === compact);
}

/**
 * Placeholder used when nothing in the register matches. It carries no rate —
 * every figure on the row reads zero and the line is flagged, because inventing
 * a plausible heading is worse than admitting the register has no answer.
 */
export const UNCLASSIFIED: TariffEntry = {
  hs: "—",
  hsCompact: "",
  hs6: "",
  titleId: "Belum diklasifikasi",
  titleEn: "No heading assigned",
  uom: "PCE",
  bmMfn: 0,
  bmMax: 0,
  bmExact: false,
  bmAcf: 0,
  bmAsean: 0,
  ppnbm: 0,
  lartas: "NONE",
  risk: "HIGH",
  rationale: "No heading in the register matched this description.",
  fta: {},
  keys: [],
  caution: "Assign an HS code before filing — duty cannot be computed for this line.",
};

/** How many national lines the register actually covers. */
export const REGISTER_SIZE = TARIFF.length;
